import { trigger, transition, style, animate } from '@angular/animations';
import { Component } from '@angular/core';
import { Router } from '@angular/router';
@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
  animations: [
  trigger('slideInFooter', [
    transition(':enter', [
      style({ transform: 'translateY(100%)', opacity: 0 }),
      animate('500ms ease-out', style({ transform: 'translateY(0)', opacity: 1 }))
    ])
  ])
]

})
export class AppComponent {
  title = 'KarmineVersusOpps';

  constructor(public router: Router) {}
  isHome(): boolean {
    return this.router.url === '/';
  }
}

<div class="app-wrapper">
  <mat-toolbar>
    <img src="assets/img/KarmineCorp.svg" id="kc-logo" alt="KC logo" />
  </mat-toolbar>

  <main class="app-main">
    <router-outlet></router-outlet>
  </main>

  <footer class="app-footer" @slideInFooter>
    <div class="footer-content">
      <span class="footer-left">© 2025 Karmine Versus Opps</span>
      <span class="footer-right">Fait avec ❤️ par moi</span>
    </div>
  </footer>
</div>
